import { pool, transaction } from '../../../packages/database/src/pool.js';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  idempotency_key: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
  last_error: string | null;
}

export interface ClaimedErasureRequest extends ErasureRequestRow {
  locked_by: string;
  locked_at: Date;
  lease_expires_at: Date;
}

/** Stable erasure request body returned by the privacy API. */
export interface ErasureRequestResponse {
  id: string;
  customerId: string;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

export const ERASURE_REQUEST_STATUSES = ['pending', 'processing', 'failed', 'completed'] as const;
export type ErasureRequestStatus = typeof ERASURE_REQUEST_STATUSES[number];

export function toErasureResponse(row: ErasureRequestRow): ErasureRequestResponse {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureRepository {
  async findForCustomer(merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,idempotency_key,created_at,updated_at,completed_at,last_error
       FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findById(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,idempotency_key,created_at,updated_at,completed_at,last_error
       FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  /** Inserts the erasure request row, returning the existing one if the customer already has one. */
  async upsert(client: PoolClient, merchantId: string, customerId: string,
                idempotencyKey: string): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key)
       VALUES($1,$2,$3)
       ON CONFLICT(merchant_id,customer_id) DO UPDATE
       SET updated_at = customers.erasure_requests.updated_at
       RETURNING id,merchant_id,customer_id,status,attempts,idempotency_key,created_at,updated_at,completed_at,last_error`,
      [merchantId, customerId, idempotencyKey],
    );
    return result.rows[0]!;
  }

  async claimNext(workerId: string, leaseSeconds = 60): Promise<ClaimedErasureRequest | undefined> {
    return await transaction(async (client) => {
      const result = await client.query<ClaimedErasureRequest>(
        `UPDATE customers.erasure_requests
         SET status='processing',attempts=attempts+1,locked_by=$1,locked_at=now(),
             lease_expires_at=now()+($2 || ' seconds')::interval,updated_at=now(),last_error=NULL
         WHERE id=(SELECT id FROM customers.erasure_requests
           WHERE status IN ('pending','failed') AND next_attempt_at<=now()
           ORDER BY next_attempt_at,created_at FOR UPDATE SKIP LOCKED LIMIT 1)
         RETURNING id,merchant_id,customer_id,status,attempts,idempotency_key,
                   created_at,updated_at,completed_at,last_error,
                   locked_by,locked_at,lease_expires_at`,
        [workerId, leaseSeconds],
      );
      return result.rows[0];
    });
  }

  async recoverExpiredLeases(): Promise<number> {
    const result = await pool.query(
      `UPDATE customers.erasure_requests
       SET status='pending',next_attempt_at=now(),locked_by=NULL,locked_at=NULL,
           lease_expires_at=NULL,last_error=COALESCE(last_error,'worker_lease_expired')
       WHERE status='processing' AND lease_expires_at<now()`,
    );
    return result.rowCount ?? 0;
  }

  async complete(client: PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed',completed_at=now(),updated_at=now(),
           locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,last_error=NULL
       WHERE id=$1`,
      [requestId],
    );
  }

  async failRetry(client: PoolClient, requestId: string, errorCode: string, retryAfterSeconds: number): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='failed',next_attempt_at=now()+($2 || ' seconds')::interval,
           updated_at=now(),locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,last_error=$3
       WHERE id=$1`,
      [requestId, retryAfterSeconds, errorCode],
    );
  }
}"}

