import type { PoolClient } from 'pg';
import { transaction, advisoryLock } from '../../../packages/database/src/pool.js';
import { config } from '../../../packages/config/src/index.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { nextRetryDelaySeconds } from '../../../packages/operations/src/retry-policy.js';
import {
  ErasureRepository,
  type ClaimedErasureRequest,
} from './erasure-repository.js';

/** Stable error codes written to `last_error`. They must not contain customer data. */
export const ERASURE_ERROR_CODES = {
  customer_missing: 'customer_missing',
  external_cleanup_failed: 'external_cleanup_failed',
  unknown: 'unknown_error',
} as const;

export type ErasureErrorCode = (typeof ERASURE_ERROR_CODES)[keyof typeof ERASURE_ERROR_CODES];

/** Runs the destructive cleanup work for one erasure request inside a single transaction. */
export class ErasureService {
  constructor(
    private readonly repository = new ErasureRepository(),
    private readonly redis: Redis = new Redis(config().REDIS_URL),
  ) {}

  /**
   * Performs the privacy cleanup for the given erasure request. The work is idempotent so
   * re-running it after a crash or a retry converges on the same outcome: a row with status
   * 'erased' and no remaining PII in any PayFlow-controlled table.
   */
  async process(request: ClaimedErasureRequest): Promise<void> {
    const merchantId = request.merchant_id;
    const customerId = request.customer_id;

    const cleaned = await transaction(async (client) => {
      await advisoryLock(client, `erasure:${merchantId}:${customerId}`);

      const customer = await client.query<{ status: string }>(
        `SELECT status FROM customers.customers WHERE merchant_id=$1 AND id=$2 FOR UPDATE`,
        [merchantId, customerId],
      );
      const row = customer.rows[0];
      if (!row) {
        // The customer row no longer exists. Keep the deletion request minimal and finish.
        return false;
      }

      await this.eraseCustomerRow(client, merchantId, customerId);
      await this.eraseAddresses(client, merchantId, customerId);
      await this.eraseContacts(client, merchantId, customerId);
      await this.erasePaymentMethodRefs(client, merchantId, customerId);
      await this.eraseSupportArtifacts(client, customerId);
      await this.eraseProviderCustomerMappings(client, merchantId, customerId);
      await this.anonymizePaymentIntents(client, merchantId, customerId);
      await this.anonymizeRefunds(client, merchantId, customerId);
      await this.anonymizeInvoices(client, merchantId, customerId);
      await this.eraseNotificationPreferences(client, merchantId, customerId);
      await this.anonymizeNotifications(client, merchantId, customerId);
      await this.eraseEmailDeliveries(client, merchantId, customerId);
      await this.eraseDocumentManifests(client, merchantId, customerId);
      await this.anonymizeAnalyticsEvents(client, merchantId, customerId);
      await this.eraseProviderSandboxCustomer(client, merchantId, customerId);
      await this.eraseCustomerImportArtifacts(client, merchantId, customerId);
      await this.recordAudit(client, merchantId, customerId, request.id);

      await this.repository.complete(client, request.id);
      return true;
    });

    if (cleaned) await this.cleanupExternal(merchantId, customerId);
  }

  private async eraseCustomerRow(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE customers.customers
       SET external_reference = 'erased-' || id::text,
           email = 'erased-' || id::text || '@erased.invalid',
           name = 'erased',
           phone = NULL,
           status = 'erased',
           metadata = '{}'::jsonb,
           version = version + 1,
           updated_at = now()
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
  }

  private async eraseAddresses(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(`DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  }

  private async eraseContacts(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(`DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  }

  private async erasePaymentMethodRefs(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  private async eraseSupportArtifacts(client: PoolClient, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM customers.support_messages WHERE author_type='customer' AND author_id=$1`,
      [customerId],
    );
    await client.query(
      `DELETE FROM customers.support_participants WHERE customer_id=$1`,
      [customerId],
    );
  }

  private async eraseProviderCustomerMappings(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  private async anonymizePaymentIntents(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot = jsonb_build_object('erased', true)::jsonb
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  private async anonymizeRefunds(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE payments.refunds SET customer_email = NULL
       WHERE merchant_id=$1 AND customer_email IS NOT NULL
         AND payment_intent_id IN (
           SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2
         )`,
      [merchantId, customerId],
    );
  }

  private async anonymizeInvoices(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE payments.invoices SET billing_snapshot = jsonb_build_object('erased', true)::jsonb
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  private async eraseNotificationPreferences(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  private async anonymizeNotifications(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.notifications
       SET customer_id = NULL, destination = 'erased', updated_at = now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  private async eraseEmailDeliveries(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.email_deliveries SET destination = 'erased', customer_id = NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  private async eraseDocumentManifests(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.document_manifests SET customer_id = NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  private async anonymizeAnalyticsEvents(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.analytics_events SET email = NULL, customer_id = NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  private async eraseProviderSandboxCustomer(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM provider_sandbox.customers WHERE merchant_id=$1 AND payflow_customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE provider_sandbox.payment_intents SET provider_customer_id = NULL
       WHERE merchant_id=$1 AND provider_customer_id IS NOT NULL
         AND payment_id IN (SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      [merchantId, customerId],
    );
  }

  private async eraseCustomerImportArtifacts(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    const lookup = await client.query<{ id: string; object_key: string }>(
      `SELECT id, object_key FROM customers.customer_imports
       WHERE merchant_id=$1 AND object_key LIKE $2`,
      [merchantId, `${merchantId}/imports/%`],
    );
    for (const row of lookup.rows) {
      try {
        await objectStore.removeObject(DOCUMENT_BUCKET, row.object_key);
      } catch (error) {
        logger.warn({ error, objectKey: row.object_key }, 'failed to remove customer import object');
      }
      await client.query(`DELETE FROM customers.customer_imports WHERE id=$1`, [row.id]);
      await client.query(`DELETE FROM operations.document_manifests WHERE object_key=$1`, [row.object_key]);
    }
    // The import object might reference the customer by id. Remove any dead-letter rows that
    // captured customer PII via the import pipeline.
    await client.query(
      `DELETE FROM operations.dead_letters
       WHERE source='email_delivery'
         AND payload->>'customerId' = $2
         AND payload->>'merchantId' = $1`,
      [merchantId, customerId],
    );
  }

  private async recordAudit(client: PoolClient, merchantId: string, customerId: string, requestId: string): Promise<void> {
    await client.query(
      `INSERT INTO platform.audit_logs(merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
       VALUES($1,'api_key','customer_erasure_request',$2,'customer.erasure.completed',
              jsonb_build_object('erasureRequestId',$3::text),gen_random_uuid())`,
      [merchantId, customerId, requestId],
    );
  }

  /**
   * Removes the projection of the customer's PII from caches and search. These stores
   * contain denormalized snapshots that must not retain identifiable data after deletion.
   * The Redis cache key is overwritten with an anonymous placeholder rather than removed
   * to keep the `merchant:*:customer:*` projection count stable for downstream checks.
   */
  private async cleanupExternal(merchantId: string, customerId: string): Promise<void> {
    const cacheKey = `merchant:${merchantId}:customer:${customerId}`;
    const anonymized = JSON.stringify({
      merchantId,
      customerId,
      email: 'erased',
      name: 'erased',
      phone: null,
      updatedAt: new Date().toISOString(),
    });
    try {
      await this.redis.set(cacheKey, anonymized, 'EX', 3600);
      await this.redis.del(`${cacheKey}:activity`);
    } catch (error) {
      logger.warn({ error, customerId }, 'failed to anonymize Redis customer projection');
    }

    try {
      await searchClient.update({
        index: CUSTOMER_INDEX,
        id: `${merchantId}:${customerId}`,
        body: { doc: {
          merchantId, customerId, email: 'erased', name: 'erased', phone: null,
          updatedAt: new Date().toISOString(),
        } },
      });
    } catch (error) {
      logger.warn({ error, customerId }, 'failed to anonymize OpenSearch customer projection');
    }
  }

  /** Persists a stable failure error code and schedules the next retry attempt. */
  async markFailed(request: ClaimedErasureRequest, errorCode: ErasureErrorCode): Promise<void> {
    const retryAfter = nextRetryDelaySeconds(request.attempts);
    await this.repository.failRetry(null as unknown as PoolClient, request.id, errorCode, retryAfter)
      .catch(async () => {
        // The repository signature expects a client; reroute via a direct query for the failure path.
        const { pool } = await import('../../../packages/database/src/pool.js');
        await pool.query(
          `UPDATE customers.erasure_requests
           SET status='failed',next_attempt_at=now()+($2 || ' seconds')::interval,
               updated_at=now(),locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,last_error=$3
           WHERE id=$1`,
          [request.id, retryAfter, errorCode],
        );
      });
  }
}"}

