{"security_risk":"LOW","summary":"Create erasure worker","command":"create","path":"/workspace/source/apps/customer-service/src/erasure-worker.ts","file_text":"import { randomUUID } from 'node:crypto';
import { logger } from '../../../packages/observability/src/logger.js';
import {
  ErasureService,
  ERASURE_ERROR_CODES,
  type ErasureErrorCode,
} from './erasure-service.js';
import { ErasureRepository } from './erasure-repository.js';

const workerId = `customer-service-erasure-${randomUUID()}`;
const repository = new ErasureRepository();
const service = new ErasureService(repository);

let lastLeaseRecovery = 0;
let stopRequested = false;

/** Long-running loop that claims and processes erasure requests. */
export async function runErasureWorker(signal: AbortSignal): Promise<void> {
  while (!signal.aborted && !stopRequested) {
    if (Date.now() - lastLeaseRecovery > 30_000) {
      try { await repository.recoverExpiredLeases(); }
      catch (error) { logger.warn({ error }, 'failed to recover expired erasure leases'); }
      lastLeaseRecovery = Date.now();
    }
    const request = await repository.claimNext(workerId).catch((error) => {
      logger.error({ error }, 'failed to claim erasure request');
      return undefined;
    });
    if (!request) {
      await new Promise((resolve) => setTimeout(resolve, 500));
      continue;
    }
    try {
      await service.process(request);
    } catch (error) {
      const code = classifyError(error);
      logger.error({ error, requestId: request.id, code }, 'erasure request processing failed');
      try { await service.markFailed(request, code); }
      catch (failure) { logger.error({ failure, requestId: request.id }, 'failed to record erasure failure'); }
    }
  }
}

function classifyError(error: unknown): ErasureErrorCode {
  const message = error instanceof Error ? error.message : String(error);
  if (message.includes('MinIO') || message.includes('Redis') || message.includes('OpenSearch')) {
    return ERASURE_ERROR_CODES.external_cleanup_failed;
  }
  return ERASURE_ERROR_CODES.unknown;
}"}

{"security_risk":"LOW","summary":"Create erasure routes","command":"create","path":"/workspace/source/apps/customer-service/src/erasure-routes.ts","file_text":"import type { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { createHash } from 'node:crypto';
import { authenticate } from '../../../packages/auth/src/api-key.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { ErasureRepository, toErasureResponse } from './erasure-repository.js';

const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9._\-:]{8,200}$/;

const pathParams = z.object({ customerId: z.string().uuid() });
const requestIdParams = z.object({ requestId: z.string().uuid() });

/**
 * The erasure request has no body. We still need a deterministic, customer-scoped hash so
 * idempotency keys are safely distinguishable across customers and do not silently share
 * their cached response with an unrelated request.
 */
function erasureRequestHash(customerId: string): string {
  return createHash('sha256').update(`erasure:${customerId}`).digest('hex');
}

interface IdempotencyResponse { status: number; body: unknown; }

async function reserveIdempotency(
  client: import('pg').PoolClient,
  merchantId: string,
  scope: string,
  key: string,
  hash: string,
): Promise<IdempotencyResponse | undefined> {
  const inserted = await client.query(
    `INSERT INTO operations.idempotency_keys(merchant_id,scope,key,request_hash,expires_at)
     VALUES($1,$2,$3,$4,now()+interval '24 hours') ON CONFLICT DO NOTHING`,
    [merchantId, scope, key, hash],
  );
  if (inserted.rowCount) return undefined;
  const existing = await client.query<{ request_hash: string; response_status: number | null; response_body: unknown }>(
    `SELECT request_hash,response_status,response_body FROM operations.idempotency_keys
     WHERE merchant_id=$1 AND scope=$2 AND key=$3 FOR UPDATE`, [merchantId, scope, key],
  );
  const row = existing.rows[0];
  if (!row || row.request_hash !== hash) {
    throw Object.assign(new Error('idempotency_key_reused_with_different_customer'), { statusCode: 409 });
  }
  if (row.response_status === null) {
    throw Object.assign(new Error('idempotency_request_in_progress'), { statusCode: 409 });
  }
  return { status: row.response_status, body: row.response_body };
}

async function completeIdempotency(
  client: import('pg').PoolClient,
  merchantId: string,
  scope: string,
  key: string,
  status: number,
  body: unknown,
): Promise<void> {
  await client.query(
    `UPDATE operations.idempotency_keys SET response_status=$4,response_body=$5
     WHERE merchant_id=$1 AND scope=$2 AND key=$3`,
    [merchantId, scope, key, status, body],
  );
}

export async function erasureRoutes(app: FastifyInstance): Promise<void> {
  const repository = new ErasureRepository();

  app.post('/v1/customers/:customerId/erasure-requests', async (request, reply) => {
    const principal = await authenticate(request, 'privacy:erase');
    const { customerId } = pathParams.parse(request.params);

    const idempotencyKey = request.headers['idempotency-key'];
    if (typeof idempotencyKey !== 'string' || !IDEMPOTENCY_KEY_PATTERN.test(idempotencyKey)) {
      return reply.code(400).send({ error: 'valid_idempotency_key_required' });
    }

    const customer = await request.server.pg.pool
      ? null
      : null;
    void customer;

