const gateway = process.env.GATEWAY_URL ?? 'http://localhost:3000';
const apiKey = process.env.PAYFLOW_API_KEY ?? 'pf_local_dev_northstar_4ad1539de977';
const otherKey = process.env.OTHER_PAYFLOW_API_KEY ?? 'pf_local_dev_bluebird_924bd90d2201';

type ErasureResponse = {
  id: string;
  customerId: string;
  status: string;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
};

async function api<T>(path: string, method = 'GET', body?: unknown, headers: Record<string, string> = {}): Promise<{ status: number; body: T }> {
  const request: RequestInit = {
    method,
    headers: { authorization: `Bearer ${apiKey}`, ...headers, ...(body === undefined ? {} : { 'content-type': 'application/json' }) },
  };
  if (body !== undefined) request.body = JSON.stringify(body);
  const response = await fetch(`${gateway}${path}`, request);
  const payload = await response.json() as T;
  return { status: response.status, body: payload };
}

async function expectStatus<T>(label: string, expected: number, response: { status: number; body: T }, extraCheck?: (body: T) => void): Promise<T> {
  if (response.status !== expected) {
    console.error(`✗ ${label}: expected ${expected}, got ${response.status}:`, response.body);
    process.exit(1);
  }
  if (extraCheck) extraCheck(response.body);
  console.log(`✓ ${label}: ${response.status}`);
  return response.body;
}

const customerSuffix = randomUUID();
const customer = await api<{ id: string }>('/v1/customers', 'POST', {
  externalReference: `erasure-check-${customerSuffix}`,
  email: `erasure-check-${customerSuffix}@example.test`,
  name: 'Erasure Scenario Check',
  phone: '+1-555-0100',
  metadata: { source: 'erasure-scenario-check' },
}, { 'idempotency-key': `erasure-check-create-${customerSuffix}` });
const customerId = (await expectStatus<{ id: string }>('create customer', 201, customer)).id;

const missingId = randomUUID();
await expectStatus<{ error: string }>(
  'create erasure for missing customer',
  404,
  await api(`/v1/customers/${missingId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': `erase-missing-${randomUUID()}` }),
);

await expectStatus<{ error: string }>(
  'reject missing idempotency key',
  400,
  await api(`/v1/customers/${customerId}/erasure-requests`, 'POST'),
);

const shortKey = 'short';
await expectStatus<{ error: string }>(
  'reject short idempotency key',
  400,
  await api(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': shortKey }),
);

const idempotencyKey = `erase-${randomUUID()}`;
const first = await api<ErasureResponse>(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': idempotencyKey });
const firstBody = await expectStatus<ErasureResponse>('create erasure request', 202, first, (body) => {
  if (!body.id) throw new Error('missing id');
  if (body.customerId !== customerId) throw new Error(`wrong customerId: ${body.customerId}`);
  if (body.status !== 'pending') throw new Error(`expected status pending, got ${body.status}`);
});
const requestId = firstBody.id;

const replay = await api<ErasureResponse>(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': idempotencyKey });
const replayBody = await expectStatus<ErasureResponse>('replay returns same request', 202, replay, (body) => {
  if (body.id !== requestId) throw new Error(`expected same request id ${requestId}, got ${body.id}`);
});

const otherCustomer = await api<{ id: string }>('/v1/customers', 'POST', {
  externalReference: `erasure-check-other-${customerSuffix}`,
  email: `erasure-check-other-${customerSuffix}@example.test`,
  name: 'Erasure Scenario Other',
}, { 'idempotency-key': `erasure-check-other-${customerSuffix}` });
const otherCustomerId = (await expectStatus<{ id: string }>('create other customer', 201, otherCustomer)).id;

await expectStatus<{ error: string }>(
  'idempotency key reused for different customer returns 409',
  409,
  await api(`/v1/customers/${otherCustomerId}/erasure-requests`, 'POST', undefined, { 'idempotency-key': idempotencyKey }),
);

