    return ERASURE_ERROR_CODES.external_cleanup_failed;
  }
  return ERASURE_ERROR_CODES.unknown;
}","new_str":"function classifyError(error: unknown): ErasureErrorCode {
  if (!error || typeof error !== 'object') return ERASURE_ERROR_CODES.unknown;
  const name = (error as { name?: string }).name ?? '';
  const stack = error instanceof Error ? error.stack ?? '' : '';
  const blob = `${name} ${stack}`;
  if (blob.includes('opensearch') || blob.includes('OpenSearch') || blob.includes('ResponseError')) {
    return ERASURE_ERROR_CODES.external_cleanup_failed;
  }
  if (blob.includes('Redis') || blob.includes('ioredis')) {
    return ERASURE_ERROR_CODES.external_cleanup_failed;
  }
  if (blob.includes('S3') || blob.includes('MinIO') || blob.includes('minio')) {
    return ERASURE_ERROR_CODES.external_cleanup_failed;
  }
  return ERASURE_ERROR_CODES.unknown;
}"}

